import type { InjectionKey, Ref } from 'vue'

export const menuGroup: InjectionKey<boolean> = Symbol('p0seid0n-menu-group')

export const menuRadioValue: InjectionKey<Ref<string | undefined>> = Symbol('p0seid0n-menu-radio')

export function emitMenuSelect(event: Event, emit: (event: Event) => void) {
  const selection = new CustomEvent('menu.itemSelect', { bubbles: true, cancelable: true })
  emit(selection)
  if (selection.defaultPrevented) event.preventDefault()
}

import type {
  DialogFinalFocus,
  DialogInitialFocus,
  DialogOpenChangeDetails,
} from '@ui-sdk/vue/dialog'
import { inject, onScopeDispose, provide, type InjectionKey } from 'vue'

export type PanelFocusProps = {
  initialFocus?: DialogInitialFocus
  finalFocus?: DialogFinalFocus
}

type DismissHandler = (details: DialogOpenChangeDetails) => void
const behaviourKey: InjectionKey<Set<DismissHandler>> = Symbol('p0seid0n-dialog')

type DismissOptions = {
  closeOnOutside: () => boolean
  closeOnEsc: () => boolean
}
const defaults: DismissOptions = {
  closeOnOutside: () => true,
  closeOnEsc: () => true,
}

export function provideDialogBehaviour(options = defaults) {
  const handlers = new Set<DismissHandler>()
  provide(behaviourKey, handlers)

  return (open: boolean, details: DialogOpenChangeDetails) => {
    if (open) return
    if (
      (details.reason === 'outside-press' && !options.closeOnOutside()) ||
      (details.reason === 'escape-key' && !options.closeOnEsc())
    ) {
      details.cancel()
    }
    for (const handler of handlers) handler(details)
  }
}

export type PointerDownOutsideEvent = CustomEvent<{ originalEvent: MouseEvent }>

type DismissEvents = {
  escapeKeyDown: (event: KeyboardEvent) => void
  pointerDownOutside: (event: PointerDownOutsideEvent) => void
  interactOutside: (event: Event) => void
}

export function useDialogDismiss(events: DismissEvents, options = defaults) {
  const handlers = inject(behaviourKey, null)
  const handler: DismissHandler = (details) => {
    const original = details.event
    if (details.reason === 'escape-key' && original instanceof KeyboardEvent) {
      const event = new KeyboardEvent(original.type, {
        key: original.key,
        code: original.code,
        altKey: original.altKey,
        ctrlKey: original.ctrlKey,
        metaKey: original.metaKey,
        shiftKey: original.shiftKey,
        cancelable: true,
      })
      if (details.canceled || !options.closeOnEsc()) event.preventDefault()
      events.escapeKeyDown(event)
      if (event.defaultPrevented) details.cancel()
    } else if (details.reason === 'outside-press' && original instanceof MouseEvent) {
      const event = new CustomEvent('dismissableLayer.pointerDownOutside', {
        cancelable: true,
        detail: { originalEvent: original },
      })
      if (details.canceled || !options.closeOnOutside()) event.preventDefault()
      events.pointerDownOutside(event)
      events.interactOutside(event)
      if (event.defaultPrevented) details.cancel()
    }
  }
  handlers?.add(handler)
  onScopeDispose(() => handlers?.delete(handler))
}

import type { InjectionKey, Ref } from 'vue'

export const tabsContext: InjectionKey<{
  loop: Ref<boolean>
  unmountOnHide: Readonly<Ref<boolean>>
}> = Symbol('p0seid0n-tabs')

export function encodeTab(value: string | number) {
  return typeof value === 'number' ? `n:${value}` : `s:${value}`
}

export function decodeTab(value: string) {
  return value.startsWith('n:') ? Number(value.slice(2)) : value.slice(2)
}

import { inject, type InjectionKey } from 'vue'

export type ToastVariant = 'default' | 'success' | 'danger'

export type ToastAction = {
  label: string
  /** Called before the notification is dismissed. */
  onClick?: () => void
}

export type ToastOptions = {
  title: string
  description?: string
  variant?: ToastVariant
  /** Overrides the provider default, in milliseconds. Zero keeps it open. */
  duration?: number
  action?: ToastAction
  /** Identity used by `dismiss`; generated when omitted. */
  id?: string
}

export type ToastRecord = ToastOptions & {
  id: string
  variant: ToastVariant
  duration: number
  /** Monotonic counter so re-pushing the same id resets its countdown. */
  version: number
}

export type ToastApi = {
  toast: (options: ToastOptions) => string
  dismiss: (id: string) => void
  dismissAll: () => void
}

export const toastKey: InjectionKey<ToastApi> = Symbol('p0seid0n-toast')

/**
 * Calling this outside a ToastProvider throws rather than silently dropping the
 * notification, so a missing provider surfaces during development.
 */
export function useToast(): ToastApi {
  const api = inject(toastKey, null)
  if (!api) {
    throw new Error('useToast() must be called inside a ToastProvider.')
  }
  return api
}

import { createOverlays } from '@ui-sdk/core/overlays'
import { createToaster, type ToastContent } from '@ui-sdk/vue/toast'
import { inject, provide, shallowRef, type InjectionKey, type Ref } from 'vue'
import type { ToastOptions, ToastRecord } from './context'

export type ToastStack = {
  items: Ref<ToastRecord[]>
  toaster: ReturnType<typeof createToaster<ToastContent>>
  push: (options: ToastOptions, duration: number, max: number) => string
  dismiss: (id: string) => void
  dismissAll: () => void
}

export const toastStackKey: InjectionKey<ToastStack> = Symbol('p0seid0n-toast-stack')

/**
 * The stack lives outside the provider component so the viewport can read the same
 * reactive list without prop drilling through slots.
 */
export function createToastStack(): ToastStack {
  const toaster = createToaster({ overlays: createOverlays() })
  const items = shallowRef<ToastRecord[]>([])
  let sequence = 0

  toaster.subscribe(() => {
    items.value = toaster
      .toasts()
      .map((toast) => toast.data as ToastRecord)
      .sort((a, b) => a.version - b.version)
  })

  function dismiss(id: string): void {
    toaster.dismiss(id)
  }

  function dismissAll(): void {
    toaster.dismiss()
  }

  function push(options: ToastOptions, duration: number, max: number): string {
    sequence += 1
    const id = options.id ?? `p0seid0n-toast-${sequence}`
    const record: ToastRecord = {
      ...options,
      id,
      variant: options.variant ?? 'default',
      duration: options.duration ?? duration,
      version: sequence,
    }

    const existing = items.value.filter((item) => item.id !== id)
    for (const oldest of existing.slice(0, Math.max(0, existing.length + 1 - Math.max(1, max)))) {
      toaster.dismiss(oldest.id)
    }

    toaster({
      id,
      title: record.title,
      description: record.description,
      type: record.variant === 'danger' ? 'error' : record.variant,
      duration: record.duration > 0 ? record.duration : Infinity,
      action: record.action
        ? { label: record.action.label, onAction: record.action.onClick, dismiss: true }
        : undefined,
      data: record,
    })
    return id
  }

  return { items, toaster, push, dismiss, dismissAll }
}

export function provideToastStack(stack: ToastStack): void {
  provide(toastStackKey, stack)
}

export function useToastStack(): ToastStack {
  const stack = inject(toastStackKey, null)
  if (!stack) {
    throw new Error('ToastProvider is required to render notifications.')
  }
  return stack
}

/**
 * Bar geometry, ported from the reference PingStrip: each bar fills 0.6 of its
 * slot and the rest is the gap to its neighbours.
 */
const BAR = 0.6
/** A value this many times the median already reaches the top, so spikes cannot flatten the rest. */
const SPIKE = 3
/** Below this many samples the median is not meaningful, so the max is used instead. */
const MIN_SAMPLES_FOR_MEDIAN = 3

function sanitize(value: number): number {
  return Number.isFinite(value) && value > 0 ? value : 0
}

function arrayMax(values: readonly number[]): number {
  let highest = 0
  for (let index = 0; index < values.length; index += 1) {
    const current = sanitize(values[index])
    if (current > highest) highest = current
  }
  return highest
}

export function median(values: readonly number[]): number {
  if (values.length === 0) return 0
  const sorted = values.map(sanitize).sort((a, b) => a - b)
  const mid = sorted.length >> 1
  return sorted.length % 2 === 0 ? (sorted[mid - 1] + sorted[mid]) / 2 : sorted[mid]
}

/**
 * Upper bound for the value axis. The reference clamps to `median * 3` so a few
 * spikes do not squash the rest; with one or two samples (or mostly zero samples)
 * it falls back to the positive median or max so fractional and idle series scale cleanly.
 */
export function scaleTop(values: readonly number[]): number {
  if (values.length === 0) return 1
  const max = arrayMax(values)
  if (max <= 0) return 1
  if (values.length < MIN_SAMPLES_FOR_MEDIAN) return max

  let med = median(values)
  if (med <= 0) {
    const positive = values.map(sanitize).filter((value) => value > 0)
    if (positive.length < MIN_SAMPLES_FOR_MEDIAN) return max
    med = median(positive)
  }
  return Math.max(1e-9, Math.min(max, med * SPIKE))
}

export type SparklineOptions = {
  values: readonly number[]
  /** Values are laid out across this many slots; the newest sits at the right edge. */
  slots?: number
  /** Upper bound of the value axis; defaults to the derived scale. */
  max?: number
}

/**
 * Builds the bar path in a `0 0 slots 1` viewBox where y grows downward, so every
 * bar is drawn from y=1 up to `1 - value / top`. Returns an empty string when there
 * is nothing to draw.
 */
export function sparklinePath({ values, slots, max }: SparklineOptions): string {
  if (values.length === 0) return ''

  // The slot count never drops below the sample count, or bars would overlap.
  const width = Math.max(slots ?? values.length, values.length)
  const explicitMax = max !== undefined && Number.isFinite(max) ? Math.max(1e-9, max) : undefined
  const top = explicitMax ?? scaleTop(values)
  const first = width - values.length
  const halfGap = (1 - BAR) / 2

  let d = ''
  for (let index = 0; index < values.length; index += 1) {
    const ratio = Math.min(1, Math.max(0, sanitize(values[index]) / top))
    const x = first + index + halfGap
    d += `M${round(x)},1V${round(1 - ratio)}h${BAR}V1Z`
  }
  return d
}

/** Trims float noise so the generated `d` stays comparable between runs. */
function round(value: number): number {
  return Math.round(value * 1000) / 1000
}

