import { computed, shallowRef, type Ref } from 'vue'

type Value = string | string[]

export function useCommandSelection(
  model: Ref<Value | undefined>,
  multiple: Readonly<Ref<boolean>>,
  disabled: Readonly<Ref<boolean>>,
  visibleChoices: Readonly<Ref<string[]>>,
  initial: Value | undefined,
) {
  const fallback = shallowRef(initial)
  const selected = computed(() => model.value ?? fallback.value)
  let anchor: string | undefined

  function update(value: Value) {
    fallback.value = value
    model.value = value
  }

  function select(value: string, event: Event) {
    if (disabled.value || event.defaultPrevented) return
    anchor = value
    update(multiple.value ? [value] : value)
  }

  function extend(value: string) {
    if (disabled.value || !multiple.value || anchor === undefined) return
    const choices = visibleChoices.value
    const start = choices.indexOf(anchor)
    const end = choices.indexOf(value)
    if (start >= 0 && end >= 0) {
      update(choices.slice(Math.min(start, end), Math.max(start, end) + 1))
    }
  }

  function isSelected(value: string) {
    return Array.isArray(selected.value) ? selected.value.includes(value) : selected.value === value
  }

  return { select, extend, isSelected }
}

export type AreaTone = 'accent' | 'accent-alt' | 'default' | 'danger'
export type AreaCurve = 'monotone' | 'linear'

export type AreaPoint = {
  x: number
  y: number
  value: number
}

export type AreaPathResult = {
  linePath: string
  areaPath: string
  points: AreaPoint[]
}

export type NormalizedSeries = {
  name: string
  values: number[]
  tone: AreaTone
}

const DEFAULT_TONES: readonly AreaTone[] = ['accent', 'accent-alt', 'default', 'danger']

function sanitizeValue(value: unknown): number {
  return typeof value === 'number' && Number.isFinite(value) && value > 0 ? value : 0
}

function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value))
}

function round(value: number): number {
  return Math.round(value * 1000) / 1000
}

/**
 * Computes a shared upper bound across one or more series without spreading
 * huge arrays into `Math.max(...)`.
 */
export function niceMax(values: readonly number[], explicitMax?: number): number {
  if (explicitMax !== undefined && Number.isFinite(explicitMax) && explicitMax > 0) {
    return explicitMax
  }
  let highest = 0
  for (let index = 0; index < values.length; index += 1) {
    const current = sanitizeValue(values[index])
    if (current > highest) highest = current
  }
  return highest > 0 ? highest : 1
}

/**
 * Builds SVG line and closed area paths inside a `0 0 width height` viewBox.
 * Uses Fritsch-Carlson monotone cubic tangents when `curve === 'monotone'` so
 * curves never overshoot local extrema.
 */
export function areaPaths(
  values: readonly number[],
  options: { max?: number; curve?: AreaCurve; width?: number; height?: number } = {},
): AreaPathResult {
  const width = options.width ?? 100
  const height = options.height ?? 100
  const curve = options.curve ?? 'monotone'

  if (values.length === 0) {
    return { linePath: '', areaPath: '', points: [] }
  }

  const top = niceMax(values, options.max)
  const padTop = 4
  const usableHeight = Math.max(1, height - padTop)

  if (values.length === 1) {
    const v = sanitizeValue(values[0])
    const y = round(padTop + usableHeight * (1 - clamp(v / top, 0, 1)))
    const linePath = `M0,${y}L${round(width)},${y}`
    const areaPath = `${linePath}L${round(width)},${round(height)}L0,${round(height)}Z`
    return {
      linePath,
      areaPath,
      points: [{ x: round(width / 2), y, value: v }],
    }
  }

  const points: AreaPoint[] = new Array(values.length)
  for (let index = 0; index < values.length; index += 1) {
    const v = sanitizeValue(values[index])
    const x = round((index / (values.length - 1)) * width)
    const y = round(padTop + usableHeight * (1 - clamp(v / top, 0, 1)))
    points[index] = { x, y, value: v }
  }

  let linePath = `M${points[0].x},${points[0].y}`

  if (curve === 'linear' || points.length === 2) {
    for (let index = 1; index < points.length; index += 1) {
      linePath += `L${points[index].x},${points[index].y}`
    }
  } else {
    const count = points.length
    const slopes = new Array<number>(count - 1)
    for (let index = 0; index < count - 1; index += 1) {
      const dx = points[index + 1].x - points[index].x || 1
      slopes[index] = (points[index + 1].y - points[index].y) / dx
    }

    const tangents = new Array<number>(count)
    tangents[0] = slopes[0]
    tangents[count - 1] = slopes[count - 2]

    for (let index = 1; index < count - 1; index += 1) {
      const prev = slopes[index - 1]
      const next = slopes[index]
      if (prev * next <= 0) {
        tangents[index] = 0
      } else {
        tangents[index] = (2 * prev * next) / (prev + next)
      }
    }

    for (let index = 0; index < count - 1; index += 1) {
      const p0 = points[index]
      const p1 = points[index + 1]
      const dx = p1.x - p0.x
      const cp1x = round(p0.x + dx / 3)
      const cp1y = round(p0.y + (tangents[index] * dx) / 3)
      const cp2x = round(p1.x - dx / 3)
      const cp2y = round(p1.y - (tangents[index + 1] * dx) / 3)
      linePath += `C${cp1x},${cp1y},${cp2x},${cp2y},${p1.x},${p1.y}`
    }
  }

  const first = points[0]
  const last = points[points.length - 1]
  const areaPath = `${linePath}L${last.x},${round(height)}L${first.x},${round(height)}Z`

  return { linePath, areaPath, points }
}

/**
 * Normalises either a single `values` array or tabular `data` rows + `categories`
 * into uniform series descriptors for AreaChart.
 */
export function normalizeAreaData(input: {
  values?: readonly number[]
  data?: readonly Record<string, unknown>[]
  categories?: readonly string[]
  index?: string
  tone?: AreaTone
  tones?: readonly AreaTone[]
}): { labels: string[]; series: NormalizedSeries[]; pointCount: number } {
  if (input.data && input.data.length > 0) {
    const rows = input.data
    const explicitCategories = input.categories?.filter((c) => c.length > 0)
    const inferredCategories =
      explicitCategories && explicitCategories.length > 0
        ? explicitCategories
        : Object.keys(rows[0]).filter(
            (key) => key !== input.index && typeof rows[0][key] === 'number',
          )

    const palette = input.tones && input.tones.length > 0 ? input.tones : DEFAULT_TONES
    const labels = rows.map((row, idx) =>
      input.index && row[input.index] != null ? String(row[input.index]) : String(idx + 1),
    )
    const series: NormalizedSeries[] = inferredCategories.map((name, idx) => ({
      name,
      values: rows.map((row) => sanitizeValue(row[name])),
      tone:
        inferredCategories.length === 1 && input.tone ? input.tone : palette[idx % palette.length],
    }))

    return { labels, series, pointCount: rows.length }
  }

  const values = input.values ?? []
  const cleaned = values.map((value) => sanitizeValue(value))
  return {
    labels: cleaned.map((_, idx) => String(idx + 1)),
    series:
      cleaned.length > 0 ? [{ name: 'Value', values: cleaned, tone: input.tone ?? 'accent' }] : [],
    pointCount: cleaned.length,
  }
}

import { definePrimitive } from '@ui-sdk/core'
import { createParts } from '@ui-sdk/vue/primitive'

type AreaChartOptions = {
  pointCount?: number
  interactive?: boolean
}

const areaChart = definePrimitive({
  name: 'p0seid0n-area-chart',
  options: { pointCount: 'number', interactive: 'boolean' },
  state: (options: AreaChartOptions) => ({
    pointCount: options.pointCount ?? 0,
    interactive: options.interactive ?? true,
    activeIndex: null as number | null,
  }),
  sync: (options) => ({
    pointCount: options.pointCount ?? 0,
    interactive: options.interactive ?? true,
  }),
  api: ({ store }) => ({
    inspect(event: PointerEvent, plot: HTMLElement) {
      const { interactive, pointCount } = store.get()
      if (!interactive || pointCount <= 0) return
      const rect = plot.getBoundingClientRect()
      if (rect.width <= 0) return
      const fraction = Math.min(1, Math.max(0, (event.clientX - rect.left) / rect.width))
      store.set({ activeIndex: Math.round(fraction * (pointCount - 1)) })
    },
    clear() {
      store.set({ activeIndex: null })
    },
  }),
  slots: (slot) => ({
    root: slot({}),
    legend: slot({}),
    plot: slot({
      state: (state) => ({ activeIndex: state.activeIndex }),
      on: {
        pointermove: (event, { api, el }) => {
          if (el) api.inspect(event, el)
        },
        pointerleave: (_, { api }) => api.clear(),
      },
    }),
    axis: slot({}),
  }),
})

export const {
  Root: AreaChartPart,
  Legend: AreaChartLegend,
  Plot: AreaChartPlot,
  Axis: AreaChartAxis,
} = createParts(areaChart, {
  root: 'div',
  legend: 'div',
  plot: 'div',
  axis: 'div',
})
